package ru.neverland.townyarmy;
import java.util.*;
import static ru.neverland.townyarmy.tactics.TacticsBook.*;
public final class TacticsBookSmoke {
 static int checks;static void check(boolean ok,String why){checks++;if(!ok)throw new AssertionError(why);}interface Work{void run()throws Exception;}static void denied(Work w,String why)throws Exception{boolean no=false;try{w.run();}catch(Exception ex){no=true;}check(no,why);}
 static UUID id(){return UUID.randomUUID();}static Entry e(UUID t,UUID p,long now){return new Entry(id(),t,p,p,"TEST","Native exact fixture",now,false);}
 static Kit kit(UUID t,UUID p,long now){return new Kit(id(),t,p,Role.MEDIC,Map.of("water",4000L),List.of("fixture-serialized-stack"),now,3600000,2,KitPhase.PLANNED,now,"Exact funded medical kit");}
 public static void main(String[] args)throws Exception{
  UUID town=id(),player=id();long now=10*DAY;var empty=State.empty();check(empty.role(town,player)==Role.SOLDIER,"old resident defaults to standard role");var profile=new Profile(town,player,Role.SAPPER,player,now);var state=empty.role(profile,e(town,player,now));check(state.role(town,player)==Role.SAPPER&&state.role(id(),player)==Role.SOLDIER,"role is bound to town and cannot follow a city switch");
  var point=new Point(id(),10,64,10);check(point.contains(point.world(),12,64,10,2)&&!point.contains(id(),10,64,10,16)&&!point.contains(point.world(),30,64,10,16),"arrival is bounded in three dimensions and exact world");denied(()->new Point(id(),Double.NaN,0,0),"non-finite position refused");
  var order=new Order(id(),town,player,Task.RALLY,"all",point,16,"Прибыть на сбор",now,now+60000,OrderPhase.OPEN,Set.of(),Set.of(),1);state=state.order(order,0,e(town,player,now));var accepted=order.mark(player,false,now+1);check(accepted.accepted().contains(player)&&accepted.arrived().isEmpty(),"acceptance alone is not arrival");denied(()->accepted.mark(player,false,now+2),"repeat acknowledgement does not fill history");var arrived=accepted.mark(player,true,now+2);check(arrived.arrived().equals(Set.of(player)),"arrival implies acceptance");denied(()->arrived.mark(id(),true,now+60000),"expired order cannot receive a late arrival");var saved=state.order(accepted,1,e(town,player,now+1));var beforeArrival=saved;denied(()->beforeArrival.order(arrived,1,e(town,player,now+2)),"stale menu cannot overwrite newer order revision");saved=saved.order(arrived,2,e(town,player,now+2));check(saved.order(arrived.close(OrderPhase.COMPLETED),3,e(town,player,now+3)).orders().get(order.id()).phase()==OrderPhase.COMPLETED,"commander closure keeps collected confirmations");
  var k=kit(town,player,now);state=State.empty().plan(k,e(town,player,now));var planned=state;denied(()->planned.plan(kit(id(),player,now+1),e(town,player,now+1)),"cross-town switch cannot bypass pending equipment");denied(()->k.phase(KitPhase.COMPLETE,"skip inventory proof",now+1),"planned kit cannot jump to delivered");state=state.kit(k.id(),KitPhase.FUNDED,"Stock receipt confirmed",now+1,player);state=state.kit(k.id(),KitPhase.ARMED,"Inventory effect armed",now+2,player);state=state.kit(k.id(),KitPhase.REVIEW,"Unknown player save",now+3,player);check(state.pending(player).isPresent(),"uncertain transfer keeps the player blocked");state=state.kit(k.id(),KitPhase.COMPLETE,"Exact marker verified",now+4,player);check(state.pending(player).isEmpty()&&state.kits().get(k.id()).cost().equals(k.cost()),"confirmation retains exact original cost");
  var one=state;denied(()->one.plan(kit(town,player,now+1000),e(town,player,now+1000)),"short cooldown prevents repeated kits");var second=kit(id(),player,now+3600000);state=state.plan(second,e(town,player,second.created()));state=state.kit(second.id(),KitPhase.FUNDED,"Confirmed resources",second.created()+1,player).kit(second.id(),KitPhase.ARMED,"Inventory armed",second.created()+2,player).kit(second.id(),KitPhase.COMPLETE,"Verified save",second.created()+3,player);var two=state;denied(()->two.plan(kit(town,player,now+7200000),e(town,player,now+7200000)),"24h cap includes another city's completed kit");
  var late=kit(town,player,now+DAY+1);state=state.plan(late,e(town,player,late.created()));state=state.kit(late.id(),KitPhase.CANCEL_PENDING,"Untouched reservation refund",late.created()+1,player).kit(late.id(),KitPhase.CANCELLED,"Exact refund acknowledged",late.created()+2,player);check(state.pending(player).isEmpty(),"cancel completes only after refund phase");var cancelled=state.kits().get(late.id());denied(()->cancelled.phase(KitPhase.FUNDED,"retry cancelled",late.created()+3),"cancelled ID cannot re-enter funding");var ids=Set.of(state.history().get(0).id());check(state.acknowledge(ids).history().get(0).audited()&&state.acknowledge(ids).revision()==state.revision(),"audit ACK does not rewrite operation revision");check(state.kits().get(k.id()).items().equals(k.items()),"original item payload remains frozen");
  System.out.println("TacticsBookSmoke PASS "+checks+" checks");
 }
}
